// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(bytes32 role, address account) public {
        // The only wallet with any role in this fresh deployment is nobody,
        // because initialize() was never called. Any fuzzed role/account
        // pair should therefore yield false for a correct hasRole.
        vm.assume(account != address(this));

        bool has = c.hasRole(role, account);
        assertTrue(!has || c.getRoleAdmin(role) != bytes32(0));
    }
}
